let current = 'en';
const loading = new Map();
/** Load a language pack (public/lang/<code>.json) once; regional variants reuse their base language. */
export async function ensureLang(code) {
  if (S[code]) return true;
  if (!loading.has(code)) {
    loading.set(code, (async () => {
      const res = await fetch(`/lang/${encodeURIComponent(code)}.json`, { headers: { Accept: 'application/json' } });
      if (!res.ok) throw new Error(String(res.status));
      const pack = await res.json();
      if (pack.base) { await ensureLang(pack.base); S[code] = { ...S[pack.base], ...(pack.ui ?? {}) }; } else S[code] = pack.ui;
      return true;
    })().catch(() => { loading.delete(code); return false; }));
  }
  return loading.get(code);
}
export function setLang(l) { current = S[l] ? l : 'en'; }
export function uiLang() { return current; }
export function hasUi(l) { return !!S[l]; }
export function tr(key, vars = {}, lang = current) {
  const s = (S[lang] ?? S.en)[key] ?? S.en[key] ?? key;
  return s.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? '');
}
export const STRINGS = S;
